foreign export ccall "hm_numeric_types_constant" ffiConstant :: Ptr Word32 -> CSize -> CString -> CString -> CString -> CString -> CString -> CString -> Ptr Word32 -> CSize -> Ptr Word32 -> CSize -> Ptr Handle -> IO CInt
ffiConstant :: Ptr Word32 -> CSize -> CString -> CString -> CString -> CString -> CString -> CString -> Ptr Word32 -> CSize -> Ptr Word32 -> CSize -> Ptr Handle -> IO CInt
ffiConstant rawName rawNameCount rawvalueXnumerator rawvalueXdenominator rawuncertaintyXnumerator rawuncertaintyXdenominator rawapproximationXnumerator rawapproximationXdenominator rawUnit rawUnitCount rawSource rawSourceCount out = numericBoundary $ do
    nameObject <- readText rawName rawNameCount
    name <- getText nameObject
    valueXnumeratorValue <- readInteger rawvalueXnumerator
    valueXdenominatorValue <- readInteger rawvalueXdenominator
    let value = valueXnumeratorValue % valueXdenominatorValue
    uncertaintyXnumeratorValue <- readInteger rawuncertaintyXnumerator
    uncertaintyXdenominatorValue <- readInteger rawuncertaintyXdenominator
    let uncertainty = uncertaintyXnumeratorValue % uncertaintyXdenominatorValue
    approximationXnumeratorValue <- readInteger rawapproximationXnumerator
    approximationXdenominatorValue <- readInteger rawapproximationXdenominator
    let approximation = approximationXnumeratorValue % approximationXdenominatorValue
    unitObject <- readText rawUnit rawUnitCount
    unit <- getText unitObject
    sourceObject <- readText rawSource rawSourceCount
    source <- getText sourceObject
    result <- pure (Constant (K.Constant name value uncertainty approximation unit source))
    checked (Right result) (`publish` out)

